INSERT INTO answer_model ("accepted","code","content_version","entity_type","id","prompt_code","replaced_by","replaces","scoring_mode","source_locator","status","doc") VALUES ('["see. “Could I see your passport, please?” is the natural, polite version. “Check” or “look at” sound a little colder in this fixed phrase."]','HSP-C02-PR-I1-AM','0.3.0-draft','answer-model','2508135a-d377-5387-ab00-9f70e8676a8b','HSP-C02-PR-I1',NULL,NULL,'objective_normalized','{"artifact":"Hospitrainity.docx","block_index":145,"chapter":2,"heading_path":["Front Desk and Check-In","Step 5. Practice"],"normalized_text_sha256":"c6f3085843849e32acaeae3c2898f546761f5989bb35bc831612cc9b6d2facad"}','published','{"accepted":["see. “Could I see your passport, please?” is the natural, polite version. “Check” or “look at” sound a little colder in this fixed phrase."],"code":"HSP-C02-PR-I1-AM","content_version":"0.3.0-draft","entity_type":"answer-model","id":"2508135a-d377-5387-ab00-9f70e8676a8b","prompt_code":"HSP-C02-PR-I1","replaced_by":null,"replaces":null,"scoring_mode":"objective_normalized","source_locator":{"artifact":"Hospitrainity.docx","block_index":145,"chapter":2,"heading_path":["Front Desk and Check-In","Step 5. Practice"],"normalized_text_sha256":"c6f3085843849e32acaeae3c2898f546761f5989bb35bc831612cc9b6d2facad"},"status":"published"}');
INSERT INTO answer_model ("accepted","code","content_version","entity_type","id","prompt_code","replaced_by","replaces","scoring_mode","source_locator","status","doc") VALUES ('["(b). It is warm, professional, and it offers help right away. Option (a) sounds cold, and tone is a real part of hospitality."]','HSP-C02-PR-I2-AM','0.3.0-draft','answer-model','f201ed49-64cd-5a89-a68c-aba698b1714d','HSP-C02-PR-I2',NULL,NULL,'objective_normalized','{"artifact":"Hospitrainity.docx","block_index":148,"chapter":2,"heading_path":["Front Desk and Check-In","Step 5. Practice"],"normalized_text_sha256":"fb1835f2ae7bcb0f87fd824ff066cade8ccd6c67ce3f63ea76caee26613a5aa3"}','published','{"accepted":["(b). It is warm, professional, and it offers help right away. Option (a) sounds cold, and tone is a real part of hospitality."],"code":"HSP-C02-PR-I2-AM","content_version":"0.3.0-draft","entity_type":"answer-model","id":"f201ed49-64cd-5a89-a68c-aba698b1714d","prompt_code":"HSP-C02-PR-I2","replaced_by":null,"replaces":null,"scoring_mode":"objective_normalized","source_locator":{"artifact":"Hospitrainity.docx","block_index":148,"chapter":2,"heading_path":["Front Desk and Check-In","Step 5. Practice"],"normalized_text_sha256":"fb1835f2ae7bcb0f87fd824ff066cade8ccd6c67ce3f63ea76caee26613a5aa3"},"status":"published"}');
INSERT INTO answer_model ("accepted","code","content_version","entity_type","id","prompt_code","replaced_by","replaces","scoring_mode","source_locator","status","doc") VALUES ('["Greet the guest, then confirm the reservation, then ask for the passport, then hand over the key. Following this order keeps everything smooth."]','HSP-C02-PR-I3-AM','0.3.0-draft','answer-model','058a58d4-0b37-5265-ae61-844e1a204866','HSP-C02-PR-I3',NULL,NULL,'objective_normalized','{"artifact":"Hospitrainity.docx","block_index":151,"chapter":2,"heading_path":["Front Desk and Check-In","Step 5. Practice"],"normalized_text_sha256":"841fd5b5fb5f97418672f8ed0153ee831a15d30fc3313b1ebb59de2d085aecd7"}','published','{"accepted":["Greet the guest, then confirm the reservation, then ask for the passport, then hand over the key. Following this order keeps everything smooth."],"code":"HSP-C02-PR-I3-AM","content_version":"0.3.0-draft","entity_type":"answer-model","id":"058a58d4-0b37-5265-ae61-844e1a204866","prompt_code":"HSP-C02-PR-I3","replaced_by":null,"replaces":null,"scoring_mode":"objective_normalized","source_locator":{"artifact":"Hospitrainity.docx","block_index":151,"chapter":2,"heading_path":["Front Desk and Check-In","Step 5. Practice"],"normalized_text_sha256":"841fd5b5fb5f97418672f8ed0153ee831a15d30fc3313b1ebb59de2d085aecd7"},"status":"published"}');
