INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C02-QZ-Q8-FB','0.3.0-draft','feedback-model','a661f7b7-5d87-5bea-97dc-54ba9226f174','[{"feedback_type":"model_reveal","text":"B. Offering to hold their luggage keeps the guest comfortable and shows you care."}]','HSP-C02-QZ-Q8',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":202,"chapter":2,"heading_path":["Front Desk and Check-In","Step 7. Quiz"],"normalized_text_sha256":"cb42711ca9f194443f9b03256bb9cb4c25667170610f8a19dc408c529f5f81d7"}','published','{"code":"HSP-C02-QZ-Q8-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"a661f7b7-5d87-5bea-97dc-54ba9226f174","messages":[{"feedback_type":"model_reveal","text":"B. Offering to hold their luggage keeps the guest comfortable and shows you care."}],"prompt_code":"HSP-C02-QZ-Q8","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":202,"chapter":2,"heading_path":["Front Desk and Check-In","Step 7. Quiz"],"normalized_text_sha256":"cb42711ca9f194443f9b03256bb9cb4c25667170610f8a19dc408c529f5f81d7"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C02-RP-FREE-FB','0.3.0-draft','feedback-model','93747995-0b13-5679-9ad9-f28aaf721ee7','[{"feedback_type":"model_reveal","text":"“Good evening, welcome to the Grand Serenata Hotel. Yes, we do have a room available for tonight, a lovely Deluxe Room. Would you like to take it? Wonderful. I will just need your passport and a card for the deposit, and I will have you checked in right away.” This works because it greets warmly, offers a clear solution, and moves smoothly into the steps."}]','HSP-C02-RP-FREE',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":176,"chapter":2,"heading_path":["Front Desk and Check-In","Step 6. Role-play"],"normalized_text_sha256":"39f3f936ff4ae160b5027a894025a470b8133aa756f5f776b75f21b458ea164b"}','published','{"code":"HSP-C02-RP-FREE-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"93747995-0b13-5679-9ad9-f28aaf721ee7","messages":[{"feedback_type":"model_reveal","text":"“Good evening, welcome to the Grand Serenata Hotel. Yes, we do have a room available for tonight, a lovely Deluxe Room. Would you like to take it? Wonderful. I will just need your passport and a card for the deposit, and I will have you checked in right away.” This works because it greets warmly, offers a clear solution, and moves smoothly into the steps."}],"prompt_code":"HSP-C02-RP-FREE","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":176,"chapter":2,"heading_path":["Front Desk and Check-In","Step 6. Role-play"],"normalized_text_sha256":"39f3f936ff4ae160b5027a894025a470b8133aa756f5f776b75f21b458ea164b"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C02-RP-G1-FB','0.3.0-draft','feedback-model','24165e6e-9fbf-56bd-bf92-385c184ac406','[{"feedback_type":"error_specific","text":"(a) “I do not know. Check your email.” This is unhelpful and pushes the problem back to the guest."},{"feedback_type":"success","text":"(b) “No problem at all, let me check that for you. May I have your name, please?” This is the ideal answer. It reassures the guest and moves calmly to the next step."},{"feedback_type":"error_specific","text":"(c) “That is not my job.” This is rude and unprofessional."}]','HSP-C02-RP-G1',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":158,"chapter":2,"heading_path":["Front Desk and Check-In","Step 6. Role-play"],"normalized_text_sha256":"4f59f7227de2b9b044cb848e77881f77e9c2754571e2df4ae512a61fca716a42"}','published','{"code":"HSP-C02-RP-G1-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"24165e6e-9fbf-56bd-bf92-385c184ac406","messages":[{"feedback_type":"error_specific","text":"(a) “I do not know. Check your email.” This is unhelpful and pushes the problem back to the guest."},{"feedback_type":"success","text":"(b) “No problem at all, let me check that for you. May I have your name, please?” This is the ideal answer. It reassures the guest and moves calmly to the next step."},{"feedback_type":"error_specific","text":"(c) “That is not my job.” This is rude and unprofessional."}],"prompt_code":"HSP-C02-RP-G1","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":158,"chapter":2,"heading_path":["Front Desk and Check-In","Step 6. Role-play"],"normalized_text_sha256":"4f59f7227de2b9b044cb848e77881f77e9c2754571e2df4ae512a61fca716a42"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C02-RP-G2-FB','0.3.0-draft','feedback-model','eb2fddf2-39db-54eb-a8d9-70b963db8ff3','[{"feedback_type":"success","text":"(a) “Let me see what I can do for you. We have a room on the fourth floor with a city view. Would that suit you?” This is the ideal answer, because it offers a solution warmly."},{"feedback_type":"error_specific","text":"(b) “Maybe. We will see.” This is vague and sounds dismissive."},{"feedback_type":"error_specific","text":"(c) “All rooms are the same.” This shuts the guest down instead of helping."}]','HSP-C02-RP-G2',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":163,"chapter":2,"heading_path":["Front Desk and Check-In","Step 6. Role-play"],"normalized_text_sha256":"221843c2818e55314cbba7f6b327606f4b7eae171a2d28cfdf40c4ab92da112d"}','published','{"code":"HSP-C02-RP-G2-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"eb2fddf2-39db-54eb-a8d9-70b963db8ff3","messages":[{"feedback_type":"success","text":"(a) “Let me see what I can do for you. We have a room on the fourth floor with a city view. Would that suit you?” This is the ideal answer, because it offers a solution warmly."},{"feedback_type":"error_specific","text":"(b) “Maybe. We will see.” This is vague and sounds dismissive."},{"feedback_type":"error_specific","text":"(c) “All rooms are the same.” This shuts the guest down instead of helping."}],"prompt_code":"HSP-C02-RP-G2","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":163,"chapter":2,"heading_path":["Front Desk and Check-In","Step 6. Role-play"],"normalized_text_sha256":"221843c2818e55314cbba7f6b327606f4b7eae171a2d28cfdf40c4ab92da112d"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C02-RP-G3-FB','0.3.0-draft','feedback-model','4452d35e-7514-5eeb-8c76-af9fe030a7ed','[{"feedback_type":"error_specific","text":"(a) “No, check-in is at 2. Come back later.” This is cold and unhelpful."},{"feedback_type":"success","text":"(b) “Let me check whether your room is ready. If it is not quite ready yet, I would be happy to store your luggage so you can relax in the meantime.” This is the ideal answer, warm and solution-focused."},{"feedback_type":"error_specific","text":"(c) “That is against the rules.” This hides behind policy instead of helping."}]','HSP-C02-RP-G3',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":168,"chapter":2,"heading_path":["Front Desk and Check-In","Step 6. Role-play"],"normalized_text_sha256":"668e51afa5a29312f201e5bb3eff3a4886b938ae117e5e4f6db6f4bf24cee1a8"}','published','{"code":"HSP-C02-RP-G3-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"4452d35e-7514-5eeb-8c76-af9fe030a7ed","messages":[{"feedback_type":"error_specific","text":"(a) “No, check-in is at 2. Come back later.” This is cold and unhelpful."},{"feedback_type":"success","text":"(b) “Let me check whether your room is ready. If it is not quite ready yet, I would be happy to store your luggage so you can relax in the meantime.” This is the ideal answer, warm and solution-focused."},{"feedback_type":"error_specific","text":"(c) “That is against the rules.” This hides behind policy instead of helping."}],"prompt_code":"HSP-C02-RP-G3","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":168,"chapter":2,"heading_path":["Front Desk and Check-In","Step 6. Role-play"],"normalized_text_sha256":"668e51afa5a29312f201e5bb3eff3a4886b938ae117e5e4f6db6f4bf24cee1a8"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C03-CC-SELF-FB','0.3.0-draft','feedback-model','c480ec40-cd4c-5e10-9bd7-270261c416ce','[{"feedback_type":"next_step","text":"Rate yourself honestly, from 1 (not confident yet) to 5 (very confident). This is just for you, and it is a good way to see your progress."}]','HSP-C03-CC-SELF',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":348,"chapter":3,"heading_path":["Dealing with Customers on the Phone","Step 8. Confidence check"],"normalized_text_sha256":"8ae726d271eb7a0bf90a65a1207e47b0e727c521ff95159d8c7f245ec46d05b7"}','published','{"code":"HSP-C03-CC-SELF-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"c480ec40-cd4c-5e10-9bd7-270261c416ce","messages":[{"feedback_type":"next_step","text":"Rate yourself honestly, from 1 (not confident yet) to 5 (very confident). This is just for you, and it is a good way to see your progress."}],"prompt_code":"HSP-C03-CC-SELF","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":348,"chapter":3,"heading_path":["Dealing with Customers on the Phone","Step 8. Confidence check"],"normalized_text_sha256":"8ae726d271eb7a0bf90a65a1207e47b0e727c521ff95159d8c7f245ec46d05b7"},"status":"published"}');
