INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C03-RP-FREE-FB','0.3.0-draft','feedback-model','3fb48dab-c29f-5710-b641-d952bcc227fe','[{"feedback_type":"model_reveal","text":"“Good afternoon, the Grand Serenata Hotel, Maya speaking. How may I help you? ... I would be happy to help. Let me check availability for those two nights. ... Yes, we have a room. Could I take your name and a contact number? ... Let me read that back to be sure. ... Your booking reference is four, five, three. Thank you for calling, and we look forward to welcoming you.”"}]','HSP-C03-RP-FREE',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":320,"chapter":3,"heading_path":["Dealing with Customers on the Phone","Step 6. Role-play"],"normalized_text_sha256":"c6e07fbc84e4c228fd766c2143d51057440aa0d69bcda4a46efa3b5603c6fe0c"}','published','{"code":"HSP-C03-RP-FREE-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"3fb48dab-c29f-5710-b641-d952bcc227fe","messages":[{"feedback_type":"model_reveal","text":"“Good afternoon, the Grand Serenata Hotel, Maya speaking. How may I help you? ... I would be happy to help. Let me check availability for those two nights. ... Yes, we have a room. Could I take your name and a contact number? ... Let me read that back to be sure. ... Your booking reference is four, five, three. Thank you for calling, and we look forward to welcoming you.”"}],"prompt_code":"HSP-C03-RP-FREE","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":320,"chapter":3,"heading_path":["Dealing with Customers on the Phone","Step 6. Role-play"],"normalized_text_sha256":"c6e07fbc84e4c228fd766c2143d51057440aa0d69bcda4a46efa3b5603c6fe0c"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C03-RP-G1-FB','0.3.0-draft','feedback-model','6b5bd479-6d7c-506d-b1b1-1f34435c220d','[{"feedback_type":"error_specific","text":"(a) “I do not know.” Unhelpful, and it leaves the caller stuck."},{"feedback_type":"success","text":"(b) “Let me check availability for Saturday for you. One moment, please.” This is the ideal answer, calm and action-focused."},{"feedback_type":"error_specific","text":"(c) “Probably not.” Vague and discouraging."}]','HSP-C03-RP-G1',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":302,"chapter":3,"heading_path":["Dealing with Customers on the Phone","Step 6. Role-play"],"normalized_text_sha256":"9e3f7b948942ecd2ab0168c35ed3875c6c6bd87032f5c4dafeb8df5797bec7cc"}','published','{"code":"HSP-C03-RP-G1-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"6b5bd479-6d7c-506d-b1b1-1f34435c220d","messages":[{"feedback_type":"error_specific","text":"(a) “I do not know.” Unhelpful, and it leaves the caller stuck."},{"feedback_type":"success","text":"(b) “Let me check availability for Saturday for you. One moment, please.” This is the ideal answer, calm and action-focused."},{"feedback_type":"error_specific","text":"(c) “Probably not.” Vague and discouraging."}],"prompt_code":"HSP-C03-RP-G1","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":302,"chapter":3,"heading_path":["Dealing with Customers on the Phone","Step 6. Role-play"],"normalized_text_sha256":"9e3f7b948942ecd2ab0168c35ed3875c6c6bd87032f5c4dafeb8df5797bec7cc"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C03-RP-G2-FB','0.3.0-draft','feedback-model','1603e2bc-2b0d-5675-9451-e7375eb63c47','[{"feedback_type":"error_specific","text":"(a) “I already said it.” Rude, and it makes the caller feel bad."},{"feedback_type":"success","text":"(b) “Of course. Your booking reference is four, five, two. Shall I say it again slowly?” This is the ideal answer, patient and clear."},{"feedback_type":"error_specific","text":"(c) Hanging up. Never do this."}]','HSP-C03-RP-G2',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":307,"chapter":3,"heading_path":["Dealing with Customers on the Phone","Step 6. Role-play"],"normalized_text_sha256":"7649e7be7d2d212e6701e21f10cb4e9117b1758d924aa983a0295e4260e5c251"}','published','{"code":"HSP-C03-RP-G2-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"1603e2bc-2b0d-5675-9451-e7375eb63c47","messages":[{"feedback_type":"error_specific","text":"(a) “I already said it.” Rude, and it makes the caller feel bad."},{"feedback_type":"success","text":"(b) “Of course. Your booking reference is four, five, two. Shall I say it again slowly?” This is the ideal answer, patient and clear."},{"feedback_type":"error_specific","text":"(c) Hanging up. Never do this."}],"prompt_code":"HSP-C03-RP-G2","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":307,"chapter":3,"heading_path":["Dealing with Customers on the Phone","Step 6. Role-play"],"normalized_text_sha256":"7649e7be7d2d212e6701e21f10cb4e9117b1758d924aa983a0295e4260e5c251"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C03-RP-G3-FB','0.3.0-draft','feedback-model','4c9b65a3-081c-54f1-a6f7-cd05e64e74a5','[{"feedback_type":"error_specific","text":"(a) “Wrong number.” Cold and unhelpful."},{"feedback_type":"success","text":"(b) “Of course, I will put you through to our restaurant now. One moment, please.” This is the ideal answer, because it transfers the caller warmly and clearly."},{"feedback_type":"error_specific","text":"(c) “I cannot help with that.” This leaves the caller with nowhere to go."}]','HSP-C03-RP-G3',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":312,"chapter":3,"heading_path":["Dealing with Customers on the Phone","Step 6. Role-play"],"normalized_text_sha256":"cfb177d50fd158ad6eb42981677943e7e6c6a9f1cb0411950951808871c6021b"}','published','{"code":"HSP-C03-RP-G3-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"4c9b65a3-081c-54f1-a6f7-cd05e64e74a5","messages":[{"feedback_type":"error_specific","text":"(a) “Wrong number.” Cold and unhelpful."},{"feedback_type":"success","text":"(b) “Of course, I will put you through to our restaurant now. One moment, please.” This is the ideal answer, because it transfers the caller warmly and clearly."},{"feedback_type":"error_specific","text":"(c) “I cannot help with that.” This leaves the caller with nowhere to go."}],"prompt_code":"HSP-C03-RP-G3","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":312,"chapter":3,"heading_path":["Dealing with Customers on the Phone","Step 6. Role-play"],"normalized_text_sha256":"cfb177d50fd158ad6eb42981677943e7e6c6a9f1cb0411950951808871c6021b"},"status":"published"}');
