INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C04-RP-FREE-FB','0.3.0-draft','feedback-model','30a112ed-adf1-5377-8804-f43a013f3c47','[{"feedback_type":"model_reveal","text":"“Guest services, Grand Serenata Hotel. How may I help you? ... Certainly, may I have your room number? ... May I take your order? ... Let me read that back to you: two breakfast sets and one orange juice, to room 210. That will be about twenty-five minutes. Thank you for calling, and enjoy your morning.”"}]','HSP-C04-RP-FREE',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":464,"chapter":4,"heading_path":["The Guest-Services Hotline","Step 6. Role-play"],"normalized_text_sha256":"492095c61e868053c09c1218104db2cf01222708df23363b564a0130e95f97c1"}','published','{"code":"HSP-C04-RP-FREE-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"30a112ed-adf1-5377-8804-f43a013f3c47","messages":[{"feedback_type":"model_reveal","text":"“Guest services, Grand Serenata Hotel. How may I help you? ... Certainly, may I have your room number? ... May I take your order? ... Let me read that back to you: two breakfast sets and one orange juice, to room 210. That will be about twenty-five minutes. Thank you for calling, and enjoy your morning.”"}],"prompt_code":"HSP-C04-RP-FREE","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":464,"chapter":4,"heading_path":["The Guest-Services Hotline","Step 6. Role-play"],"normalized_text_sha256":"492095c61e868053c09c1218104db2cf01222708df23363b564a0130e95f97c1"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C04-RP-G1-FB','0.3.0-draft','feedback-model','2a94e5a8-f9b9-5bef-9eba-ab391221b8c2','[{"feedback_type":"error_specific","text":"(a) “That is not my department.” Unhelpful, and it leaves the guest stuck."},{"feedback_type":"success","text":"(b) “I am sorry to hear that. I will put you through to maintenance right away. One moment, please.” This is the ideal answer, empathy followed by action."},{"feedback_type":"error_specific","text":"(c) “Try turning it off and on.” This pushes the work back onto the guest."}]','HSP-C04-RP-G1',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":446,"chapter":4,"heading_path":["The Guest-Services Hotline","Step 6. Role-play"],"normalized_text_sha256":"06447c82d431e9f97f8ab53d8eeb38191ed64e9edbccb3c2ed3c4e3474ecf43a"}','published','{"code":"HSP-C04-RP-G1-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"2a94e5a8-f9b9-5bef-9eba-ab391221b8c2","messages":[{"feedback_type":"error_specific","text":"(a) “That is not my department.” Unhelpful, and it leaves the guest stuck."},{"feedback_type":"success","text":"(b) “I am sorry to hear that. I will put you through to maintenance right away. One moment, please.” This is the ideal answer, empathy followed by action."},{"feedback_type":"error_specific","text":"(c) “Try turning it off and on.” This pushes the work back onto the guest."}],"prompt_code":"HSP-C04-RP-G1","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":446,"chapter":4,"heading_path":["The Guest-Services Hotline","Step 6. Role-play"],"normalized_text_sha256":"06447c82d431e9f97f8ab53d8eeb38191ed64e9edbccb3c2ed3c4e3474ecf43a"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C04-RP-G2-FB','0.3.0-draft','feedback-model','a2ed478b-35fe-5c70-9c36-b5ed9b8a5120','[{"feedback_type":"error_specific","text":"(a) “Everyone is in a hurry.” Dismissive and cold."},{"feedback_type":"success","text":"(b) “Of course. That is two coffees and one sandwich to your room. May I have your room number? It will be about fifteen minutes.” This is the ideal answer, fast, accurate, and warm."},{"feedback_type":"error_specific","text":"(c) “We will see.” Vague and discouraging."}]','HSP-C04-RP-G2',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":451,"chapter":4,"heading_path":["The Guest-Services Hotline","Step 6. Role-play"],"normalized_text_sha256":"5e058572544ab0749af91207d967a8642ac2a93eb6a90927776d469f05ffde0e"}','published','{"code":"HSP-C04-RP-G2-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"a2ed478b-35fe-5c70-9c36-b5ed9b8a5120","messages":[{"feedback_type":"error_specific","text":"(a) “Everyone is in a hurry.” Dismissive and cold."},{"feedback_type":"success","text":"(b) “Of course. That is two coffees and one sandwich to your room. May I have your room number? It will be about fifteen minutes.” This is the ideal answer, fast, accurate, and warm."},{"feedback_type":"error_specific","text":"(c) “We will see.” Vague and discouraging."}],"prompt_code":"HSP-C04-RP-G2","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":451,"chapter":4,"heading_path":["The Guest-Services Hotline","Step 6. Role-play"],"normalized_text_sha256":"5e058572544ab0749af91207d967a8642ac2a93eb6a90927776d469f05ffde0e"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C04-RP-G3-FB','0.3.0-draft','feedback-model','4729d941-30c4-5be7-a86b-670efdc00d4f','[{"feedback_type":"error_specific","text":"(a) “This is room service, not the front desk.” Technically true, but cold."},{"feedback_type":"success","text":"(b) “Of course, I will connect you to the front desk now. One moment, please.” This is the ideal answer, because it transfers the guest warmly and clearly."},{"feedback_type":"error_specific","text":"(c) “Call them yourself.” Rude and unhelpful."}]','HSP-C04-RP-G3',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":456,"chapter":4,"heading_path":["The Guest-Services Hotline","Step 6. Role-play"],"normalized_text_sha256":"15a46a32e0d0667892df3483a642fb23ebd34b62509337d44ff0335ad822e470"}','published','{"code":"HSP-C04-RP-G3-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"4729d941-30c4-5be7-a86b-670efdc00d4f","messages":[{"feedback_type":"error_specific","text":"(a) “This is room service, not the front desk.” Technically true, but cold."},{"feedback_type":"success","text":"(b) “Of course, I will connect you to the front desk now. One moment, please.” This is the ideal answer, because it transfers the guest warmly and clearly."},{"feedback_type":"error_specific","text":"(c) “Call them yourself.” Rude and unhelpful."}],"prompt_code":"HSP-C04-RP-G3","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":456,"chapter":4,"heading_path":["The Guest-Services Hotline","Step 6. Role-play"],"normalized_text_sha256":"15a46a32e0d0667892df3483a642fb23ebd34b62509337d44ff0335ad822e470"},"status":"published"}');
