INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C05-RP-FREE-FB','0.3.0-draft','feedback-model','d60b598a-f06e-5f4d-8412-ebb35efe9620','[{"feedback_type":"model_reveal","text":"“Dear Ms. Putri, thank you for your booking. We are pleased to confirm a Deluxe Room for one night, arriving next Friday, at 80 dollars per night, breakfast included. Your booking reference is four, six, one. We look forward to welcoming you. Kind regards, Maya, Grand Serenata Hotel.”"}]','HSP-C05-RP-FREE',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":612,"chapter":5,"heading_path":["Customer Care Through Writing","Step 6. Role-play (drafting)"],"normalized_text_sha256":"382251d29e226d009a1ab43f5455fb007b56ecfcb1fec45501f7fc51e80c357a"}','published','{"code":"HSP-C05-RP-FREE-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"d60b598a-f06e-5f4d-8412-ebb35efe9620","messages":[{"feedback_type":"model_reveal","text":"“Dear Ms. Putri, thank you for your booking. We are pleased to confirm a Deluxe Room for one night, arriving next Friday, at 80 dollars per night, breakfast included. Your booking reference is four, six, one. We look forward to welcoming you. Kind regards, Maya, Grand Serenata Hotel.”"}],"prompt_code":"HSP-C05-RP-FREE","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":612,"chapter":5,"heading_path":["Customer Care Through Writing","Step 6. Role-play (drafting)"],"normalized_text_sha256":"382251d29e226d009a1ab43f5455fb007b56ecfcb1fec45501f7fc51e80c357a"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C05-RP-G1-FB','0.3.0-draft','feedback-model','defe3fe2-f780-5cf8-a619-fae495d60f57','[{"feedback_type":"error_specific","text":"(a) “Yes.” Too short, and it answers only half of the question."},{"feedback_type":"success","text":"(b) “Dear Guest, thank you for your enquiry. Yes, we have a Double Room available this weekend at 90 dollars per night, breakfast included. Please let us know if you would like to book. Kind regards, Maya.” This is the ideal answer, complete, tidy, and warm."},{"feedback_type":"error_specific","text":"(c) “idk, check the website.” Unhelpful and far too casual."}]','HSP-C05-RP-G1',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":594,"chapter":5,"heading_path":["Customer Care Through Writing","Step 6. Role-play (drafting)"],"normalized_text_sha256":"15e97807462e79b1c359438a524519e858d66348309cfc79b1468f959ef37042"}','published','{"code":"HSP-C05-RP-G1-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"defe3fe2-f780-5cf8-a619-fae495d60f57","messages":[{"feedback_type":"error_specific","text":"(a) “Yes.” Too short, and it answers only half of the question."},{"feedback_type":"success","text":"(b) “Dear Guest, thank you for your enquiry. Yes, we have a Double Room available this weekend at 90 dollars per night, breakfast included. Please let us know if you would like to book. Kind regards, Maya.” This is the ideal answer, complete, tidy, and warm."},{"feedback_type":"error_specific","text":"(c) “idk, check the website.” Unhelpful and far too casual."}],"prompt_code":"HSP-C05-RP-G1","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":594,"chapter":5,"heading_path":["Customer Care Through Writing","Step 6. Role-play (drafting)"],"normalized_text_sha256":"15e97807462e79b1c359438a524519e858d66348309cfc79b1468f959ef37042"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C05-RP-G2-FB','0.3.0-draft','feedback-model','2c027abd-d097-5b13-920f-77fc7994fd86','[{"feedback_type":"error_specific","text":"(a) No reply at all. Silence makes the situation worse."},{"feedback_type":"success","text":"(b) “Dear Mr. Chen, thank you for letting us know, and please accept our sincere apologies. We have reviewed your bill and are correcting the duplicate charge now. The refund should appear within three to five days. Kind regards, Maya.” This is the ideal answer, an apology, ownership, and a clear action."},{"feedback_type":"error_specific","text":"(c) “That is not our fault.” Defensive and cold, and it will only anger the guest further."}]','HSP-C05-RP-G2',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":599,"chapter":5,"heading_path":["Customer Care Through Writing","Step 6. Role-play (drafting)"],"normalized_text_sha256":"4f779b0a2a47674ed07dc371955a5e540de72431a0ecf773326ce68b6958f2a2"}','published','{"code":"HSP-C05-RP-G2-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"2c027abd-d097-5b13-920f-77fc7994fd86","messages":[{"feedback_type":"error_specific","text":"(a) No reply at all. Silence makes the situation worse."},{"feedback_type":"success","text":"(b) “Dear Mr. Chen, thank you for letting us know, and please accept our sincere apologies. We have reviewed your bill and are correcting the duplicate charge now. The refund should appear within three to five days. Kind regards, Maya.” This is the ideal answer, an apology, ownership, and a clear action."},{"feedback_type":"error_specific","text":"(c) “That is not our fault.” Defensive and cold, and it will only anger the guest further."}],"prompt_code":"HSP-C05-RP-G2","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":599,"chapter":5,"heading_path":["Customer Care Through Writing","Step 6. Role-play (drafting)"],"normalized_text_sha256":"4f779b0a2a47674ed07dc371955a5e540de72431a0ecf773326ce68b6958f2a2"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C05-RP-G3-FB','0.3.0-draft','feedback-model','32137b9f-f66b-5372-8437-1610b4a88d2b','[{"feedback_type":"error_specific","text":"(a) “No.” Blunt and unfriendly."},{"feedback_type":"success","text":"(b) “Dear Ms. Putri, thank you for your message. We would be happy to offer a late check-out until 2 in the afternoon at no extra charge. Please let us know if that suits you. Kind regards, Maya.” This is the ideal answer, warm, clear, and helpful."},{"feedback_type":"error_specific","text":"(c) “That depends.” Vague, and it leaves the guest unsure."}]','HSP-C05-RP-G3',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":604,"chapter":5,"heading_path":["Customer Care Through Writing","Step 6. Role-play (drafting)"],"normalized_text_sha256":"7ba7f696b0f0de85f45d34ee4642ac1594d9ca04000cdf73e17d0e47dd9c4902"}','published','{"code":"HSP-C05-RP-G3-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"32137b9f-f66b-5372-8437-1610b4a88d2b","messages":[{"feedback_type":"error_specific","text":"(a) “No.” Blunt and unfriendly."},{"feedback_type":"success","text":"(b) “Dear Ms. Putri, thank you for your message. We would be happy to offer a late check-out until 2 in the afternoon at no extra charge. Please let us know if that suits you. Kind regards, Maya.” This is the ideal answer, warm, clear, and helpful."},{"feedback_type":"error_specific","text":"(c) “That depends.” Vague, and it leaves the guest unsure."}],"prompt_code":"HSP-C05-RP-G3","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":604,"chapter":5,"heading_path":["Customer Care Through Writing","Step 6. Role-play (drafting)"],"normalized_text_sha256":"7ba7f696b0f0de85f45d34ee4642ac1594d9ca04000cdf73e17d0e47dd9c4902"},"status":"published"}');
