INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C06-RP-FREE-FB','0.3.0-draft','feedback-model','84eb98f0-2f31-524c-8ab9-c4584d59dd94','[{"feedback_type":"model_reveal","text":"“Hi there, thanks for messaging Grand Serenata. 😊 Check-in is from 2 in the afternoon, and yes, we offer free parking for guests. Let me know if there is anything else I can help with.”"}]','HSP-C06-RP-FREE',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":752,"chapter":6,"heading_path":["Online and Social Media Customer Service","Step 6. Role-play"],"normalized_text_sha256":"6c5199cce70c58a1a21f8b4a9b472c699880aa8e23ed513d4759c97779ec4bdd"}','published','{"code":"HSP-C06-RP-FREE-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"84eb98f0-2f31-524c-8ab9-c4584d59dd94","messages":[{"feedback_type":"model_reveal","text":"“Hi there, thanks for messaging Grand Serenata. 😊 Check-in is from 2 in the afternoon, and yes, we offer free parking for guests. Let me know if there is anything else I can help with.”"}],"prompt_code":"HSP-C06-RP-FREE","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":752,"chapter":6,"heading_path":["Online and Social Media Customer Service","Step 6. Role-play"],"normalized_text_sha256":"6c5199cce70c58a1a21f8b4a9b472c699880aa8e23ed513d4759c97779ec4bdd"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C06-RP-G1-FB','0.3.0-draft','feedback-model','af6780ce-ccf1-54c1-aac8-3cb77fd92a91','[{"feedback_type":"error_specific","text":"(a) “Check our website.” Unhelpful, and it makes the guest do the work."},{"feedback_type":"success","text":"(b) “Hi there. 😊 Yes, breakfast is included in all of our room rates. Anything else I can help with?” This is the ideal answer, warm, clear, and it offers more help."},{"feedback_type":"error_specific","text":"(c) “Yes.” Correct, but a little cold. A friendly word or two would lift it."}]','HSP-C06-RP-G1',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":734,"chapter":6,"heading_path":["Online and Social Media Customer Service","Step 6. Role-play"],"normalized_text_sha256":"facefb5ad96ac857ec7f2f6881e1f22890392944d601c45f4431c615ef27d929"}','published','{"code":"HSP-C06-RP-G1-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"af6780ce-ccf1-54c1-aac8-3cb77fd92a91","messages":[{"feedback_type":"error_specific","text":"(a) “Check our website.” Unhelpful, and it makes the guest do the work."},{"feedback_type":"success","text":"(b) “Hi there. 😊 Yes, breakfast is included in all of our room rates. Anything else I can help with?” This is the ideal answer, warm, clear, and it offers more help."},{"feedback_type":"error_specific","text":"(c) “Yes.” Correct, but a little cold. A friendly word or two would lift it."}],"prompt_code":"HSP-C06-RP-G1","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":734,"chapter":6,"heading_path":["Online and Social Media Customer Service","Step 6. Role-play"],"normalized_text_sha256":"facefb5ad96ac857ec7f2f6881e1f22890392944d601c45f4431c615ef27d929"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C06-RP-G2-FB','0.3.0-draft','feedback-model','f161b909-a99b-5efc-bb22-bf303fbb66e3','[{"feedback_type":"error_specific","text":"(a) “That is not true.” Arguing in public damages the hotel’s reputation."},{"feedback_type":"success","text":"(b) “We are so sorry to hear this, and it is not the experience we want for you. Please send us a DM with your booking details so we can make it right.” This is the ideal answer, empathy in public and a move to private."},{"feedback_type":"error_specific","text":"(c) Ignoring it. Silence looks careless to everyone else reading."}]','HSP-C06-RP-G2',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":739,"chapter":6,"heading_path":["Online and Social Media Customer Service","Step 6. Role-play"],"normalized_text_sha256":"06c33fb291047f63ef592868aad2840a65e502d30b042fe4a3b521c3d8f99fdf"}','published','{"code":"HSP-C06-RP-G2-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"f161b909-a99b-5efc-bb22-bf303fbb66e3","messages":[{"feedback_type":"error_specific","text":"(a) “That is not true.” Arguing in public damages the hotel’s reputation."},{"feedback_type":"success","text":"(b) “We are so sorry to hear this, and it is not the experience we want for you. Please send us a DM with your booking details so we can make it right.” This is the ideal answer, empathy in public and a move to private."},{"feedback_type":"error_specific","text":"(c) Ignoring it. Silence looks careless to everyone else reading."}],"prompt_code":"HSP-C06-RP-G2","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":739,"chapter":6,"heading_path":["Online and Social Media Customer Service","Step 6. Role-play"],"normalized_text_sha256":"06c33fb291047f63ef592868aad2840a65e502d30b042fe4a3b521c3d8f99fdf"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C06-RP-G3-FB','0.3.0-draft','feedback-model','3cee48a0-2c09-53ea-80ff-5b62ce562244','[{"feedback_type":"error_specific","text":"(a) “Maybe.” Vague and unhelpful."},{"feedback_type":"success","text":"(b) “Of course, I would be happy to help with that. Could you send me your booking reference so I can check availability for Saturday?” This is the ideal answer, warm, and it gathers what is needed privately."},{"feedback_type":"error_specific","text":"(c) “We do not do changes.” Cold, and it shuts the guest down."}]','HSP-C06-RP-G3',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":744,"chapter":6,"heading_path":["Online and Social Media Customer Service","Step 6. Role-play"],"normalized_text_sha256":"4681dfbe07597c812edf852f5599dc381f4c4c6abf8dce2436f6e1e0474ca722"}','published','{"code":"HSP-C06-RP-G3-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"3cee48a0-2c09-53ea-80ff-5b62ce562244","messages":[{"feedback_type":"error_specific","text":"(a) “Maybe.” Vague and unhelpful."},{"feedback_type":"success","text":"(b) “Of course, I would be happy to help with that. Could you send me your booking reference so I can check availability for Saturday?” This is the ideal answer, warm, and it gathers what is needed privately."},{"feedback_type":"error_specific","text":"(c) “We do not do changes.” Cold, and it shuts the guest down."}],"prompt_code":"HSP-C06-RP-G3","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":744,"chapter":6,"heading_path":["Online and Social Media Customer Service","Step 6. Role-play"],"normalized_text_sha256":"4681dfbe07597c812edf852f5599dc381f4c4c6abf8dce2436f6e1e0474ca722"},"status":"published"}');
