INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C07-QZ-Q7-FB','0.3.0-draft','feedback-model','62f4594c-0ded-5c64-9419-f1e1b8524c0b','[{"feedback_type":"model_reveal","text":"B. You can be sorry for the experience without assigning blame."}]','HSP-C07-QZ-Q7',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":920,"chapter":7,"heading_path":["Dealing with Problems and Complaints","Step 7. Quiz"],"normalized_text_sha256":"895aaa91d40a65294739017e4561899965a9ec36573bb89bcf3e4916aa57cdcf"}','published','{"code":"HSP-C07-QZ-Q7-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"62f4594c-0ded-5c64-9419-f1e1b8524c0b","messages":[{"feedback_type":"model_reveal","text":"B. You can be sorry for the experience without assigning blame."}],"prompt_code":"HSP-C07-QZ-Q7","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":920,"chapter":7,"heading_path":["Dealing with Problems and Complaints","Step 7. Quiz"],"normalized_text_sha256":"895aaa91d40a65294739017e4561899965a9ec36573bb89bcf3e4916aa57cdcf"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C07-QZ-Q8-FB','0.3.0-draft','feedback-model','5814c21f-f363-5218-9af9-2659a26a8433','[{"feedback_type":"model_reveal","text":"A. It is the art of winning a guest back after something went wrong."}]','HSP-C07-QZ-Q8',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":923,"chapter":7,"heading_path":["Dealing with Problems and Complaints","Step 7. Quiz"],"normalized_text_sha256":"d5dbf6bd9810d8dd97a63b44ec39cce1d227599683c69e60c1b215e211bbca3b"}','published','{"code":"HSP-C07-QZ-Q8-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"5814c21f-f363-5218-9af9-2659a26a8433","messages":[{"feedback_type":"model_reveal","text":"A. It is the art of winning a guest back after something went wrong."}],"prompt_code":"HSP-C07-QZ-Q8","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":923,"chapter":7,"heading_path":["Dealing with Problems and Complaints","Step 7. Quiz"],"normalized_text_sha256":"d5dbf6bd9810d8dd97a63b44ec39cce1d227599683c69e60c1b215e211bbca3b"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C07-RP-FREE-FB','0.3.0-draft','feedback-model','184f92eb-4ba3-5feb-bfc5-ee74c6ebb2ca','[{"feedback_type":"model_reveal","text":"“I am very sorry to hear that, and I understand how frustrating it is to lose the Wi-Fi all day. This is the Listen and Apologise part. Let me send our technician to your room right away, and I will switch you to our backup network in the meantime. This is the Act part. As an apology, I would like to offer you a late check-out, and I will check back within the hour to make sure it is working. This is the Follow up part.”"}]','HSP-C07-RP-FREE',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":897,"chapter":7,"heading_path":["Dealing with Problems and Complaints","Step 6. Role-play"],"normalized_text_sha256":"c9e0d82d410a4ca305021672bb23e289ed53eb9a707e3f6b0e91ea0d5586e7bc"}','published','{"code":"HSP-C07-RP-FREE-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"184f92eb-4ba3-5feb-bfc5-ee74c6ebb2ca","messages":[{"feedback_type":"model_reveal","text":"“I am very sorry to hear that, and I understand how frustrating it is to lose the Wi-Fi all day. This is the Listen and Apologise part. Let me send our technician to your room right away, and I will switch you to our backup network in the meantime. This is the Act part. As an apology, I would like to offer you a late check-out, and I will check back within the hour to make sure it is working. This is the Follow up part.”"}],"prompt_code":"HSP-C07-RP-FREE","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":897,"chapter":7,"heading_path":["Dealing with Problems and Complaints","Step 6. Role-play"],"normalized_text_sha256":"c9e0d82d410a4ca305021672bb23e289ed53eb9a707e3f6b0e91ea0d5586e7bc"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C07-RP-G1-FB','0.3.0-draft','feedback-model','914aa31d-4228-5542-852f-61013f8baa21','[{"feedback_type":"error_specific","text":"(a) “Housekeeping usually does a good job.” This deflects instead of helping."},{"feedback_type":"success","text":"(b) “I am so sorry, that is not our standard at all. I will have it cleaned immediately, or I can move you to another room right now. Which would you prefer?” This is the ideal answer, an apology, ownership, and a choice of solution."},{"feedback_type":"error_specific","text":"(c) “Are you sure it is dirty?” This dismisses the guest and will only make it worse."}]','HSP-C07-RP-G1',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":879,"chapter":7,"heading_path":["Dealing with Problems and Complaints","Step 6. Role-play"],"normalized_text_sha256":"b611b2cf9cb9d888c1d5ab70d4e313c6aec2771a2cb01ef6aafb48cdae918cd6"}','published','{"code":"HSP-C07-RP-G1-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"914aa31d-4228-5542-852f-61013f8baa21","messages":[{"feedback_type":"error_specific","text":"(a) “Housekeeping usually does a good job.” This deflects instead of helping."},{"feedback_type":"success","text":"(b) “I am so sorry, that is not our standard at all. I will have it cleaned immediately, or I can move you to another room right now. Which would you prefer?” This is the ideal answer, an apology, ownership, and a choice of solution."},{"feedback_type":"error_specific","text":"(c) “Are you sure it is dirty?” This dismisses the guest and will only make it worse."}],"prompt_code":"HSP-C07-RP-G1","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":879,"chapter":7,"heading_path":["Dealing with Problems and Complaints","Step 6. Role-play"],"normalized_text_sha256":"b611b2cf9cb9d888c1d5ab70d4e313c6aec2771a2cb01ef6aafb48cdae918cd6"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C07-RP-G2-FB','0.3.0-draft','feedback-model','f3aa8ffa-f7a4-51b4-89e6-e01a7b92aeef','[{"feedback_type":"error_specific","text":"(a) “That is the system’s fault, not mine.” This blames something else and helps no one."},{"feedback_type":"success","text":"(b) “I am very sorry for the error. Let me check your bill and correct it right away, and you will see the refund shortly.” This is the ideal answer, an apology, action, and reassurance."},{"feedback_type":"error_specific","text":"(c) “You must have made a mistake.” This blames the guest, which is the fastest way to lose them."}]','HSP-C07-RP-G2',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":884,"chapter":7,"heading_path":["Dealing with Problems and Complaints","Step 6. Role-play"],"normalized_text_sha256":"0292edf602104be44ba29b03f52bfe103c9a6310e1a5138d3c935e903801c72a"}','published','{"code":"HSP-C07-RP-G2-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"f3aa8ffa-f7a4-51b4-89e6-e01a7b92aeef","messages":[{"feedback_type":"error_specific","text":"(a) “That is the system’s fault, not mine.” This blames something else and helps no one."},{"feedback_type":"success","text":"(b) “I am very sorry for the error. Let me check your bill and correct it right away, and you will see the refund shortly.” This is the ideal answer, an apology, action, and reassurance."},{"feedback_type":"error_specific","text":"(c) “You must have made a mistake.” This blames the guest, which is the fastest way to lose them."}],"prompt_code":"HSP-C07-RP-G2","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":884,"chapter":7,"heading_path":["Dealing with Problems and Complaints","Step 6. Role-play"],"normalized_text_sha256":"0292edf602104be44ba29b03f52bfe103c9a6310e1a5138d3c935e903801c72a"},"status":"published"}');
INSERT INTO feedback_model ("code","content_version","entity_type","id","messages","prompt_code","replaced_by","replaces","source_locator","status","doc") VALUES ('HSP-C07-RP-G3-FB','0.3.0-draft','feedback-model','7d18466b-88e0-52ac-9630-a518aa9f0dec','[{"feedback_type":"error_specific","text":"(a) “Well, nobody is perfect.” Dismissive and cold."},{"feedback_type":"success","text":"(b) “I am truly sorry, and I understand why you are frustrated after a second issue. Let me put this right now, and I will speak with my manager to make sure it does not happen again.” This is the ideal answer, empathy, action, and a follow-up promise."},{"feedback_type":"error_specific","text":"(c) “There is nothing I can do.” This gives up on the guest entirely."}]','HSP-C07-RP-G3',NULL,NULL,'{"artifact":"Hospitrainity.docx","block_index":889,"chapter":7,"heading_path":["Dealing with Problems and Complaints","Step 6. Role-play"],"normalized_text_sha256":"f804c9afb144d60de72db0ab5800755f23f3a6a9671a363b3abd15376415c9c5"}','published','{"code":"HSP-C07-RP-G3-FB","content_version":"0.3.0-draft","entity_type":"feedback-model","id":"7d18466b-88e0-52ac-9630-a518aa9f0dec","messages":[{"feedback_type":"error_specific","text":"(a) “Well, nobody is perfect.” Dismissive and cold."},{"feedback_type":"success","text":"(b) “I am truly sorry, and I understand why you are frustrated after a second issue. Let me put this right now, and I will speak with my manager to make sure it does not happen again.” This is the ideal answer, empathy, action, and a follow-up promise."},{"feedback_type":"error_specific","text":"(c) “There is nothing I can do.” This gives up on the guest entirely."}],"prompt_code":"HSP-C07-RP-G3","replaced_by":null,"replaces":null,"source_locator":{"artifact":"Hospitrainity.docx","block_index":889,"chapter":7,"heading_path":["Dealing with Problems and Complaints","Step 6. Role-play"],"normalized_text_sha256":"f804c9afb144d60de72db0ab5800755f23f3a6a9671a363b3abd15376415c9c5"},"status":"published"}');
